import React, { useEffect, useState } from "react";
import { Button, Container } from "@mui/material";
import axios from "axios";
import AuthForm from "./components/AuthForm";
import EventForm from "./components/EventForm";
import EventList from "./components/EventList";
import { initAuth, setAuthToken } from "./auth";

const API = "http://localhost:5500/api/events";

function App() {
  const [user, setUser] = useState(null);
  const [events, setEvents] = useState([]);
  const [editingEvent, setEditingEvent] = useState(null); // NEW

  // Fetch events
  const fetchEvents = async () => {
    try {
      const { data } = await axios.get(API);
      setEvents(data);
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    const token = initAuth();
    if (token) setUser({}); 
    fetchEvents();
  }, []);

  const handleLogout = () => {
    setAuthToken(null);
    setUser(null);
  };

  // DELETE EVENT
  const handleDelete = async (id) => {
    try {
      await axios.delete(`${API}/${id}`);
      fetchEvents(); // refresh list
    } catch (err) {
      console.error(err);
    }
  };

  // EDIT EVENT → send data into form
  const handleEdit = (event) => {
    setEditingEvent(event);
  };

  return !user ? (
    <AuthForm onSuccess={(usr) => setUser(usr)} />
  ) : (
    <Container sx={{ mt: 4 }}>
      <Button variant="outlined" onClick={handleLogout}>
        Logout
      </Button>

      {/* Pass event to form if editing */}
      <EventForm
        onEventAdded={fetchEvents}
        editingEvent={editingEvent}
        clearEditing={() => setEditingEvent(null)}
      />

      {/* Pass delete + edit handlers */}
      <EventList
        events={events}
        onDelete={handleDelete}
        onEdit={handleEdit}
      />
    </Container>
  );
}

export default App;
